html:
{% set view = jifeng_flow_sheet(doc) %}
{% set flow = view.flow %}
<style>.jf-head{display:flex;justify-content:space-between}.jf-photo{max-height:120px;max-width:180px}th,td{padding:6px;border-bottom:1px solid #ddd}.jf-note{white-space:pre-wrap}.jf-warning{font-weight:700}thead{display:table-header-group}tr{break-inside:avoid}</style>
<div class="jf-head"><div><h2>集沣生产流程单</h2><p>{{ (flow.get('name') or '') | e }}{% if 'company' in flow %} · {{ (flow.company or '') | e }}{% endif %}</p></div>{% if view.image_url %}<img class="jf-photo" src="{{ view.image_url | e }}">{% endif %}</div>
<p>{% if 'item_code' in flow %}商品编码：{{ (flow.item_code or '') | e }}　{% endif %}{% if 'supplier_product_code' in flow %}供应商货号：{{ (flow.supplier_product_code or '') | e }}　{% endif %}{% if 'planned_qty' in flow %}计划数量：{{ flow.planned_qty | e }}{% if 'stock_uom' in flow %} {{ (flow.stock_uom or '库存单位待核对') | e }}{% endif %}{% endif %}</p>
<p>{% if flow.get('sales_order') %}销售订单：{{ flow.sales_order | e }}　{% elif 'online_order_id' in flow %}外部订单号：{{ (flow.online_order_id or '') | e }}　{% endif %}{% if 'specification' in flow %}规格：{{ (flow.specification or '') | e }}{% endif %}{% if flow.get('work_order') %}　生产工单：{{ flow.work_order | e }}{% endif %}</p>
{% if 'source_qty' in flow %}<p>源订单数量：{{ flow.source_qty | e }}{% if 'source_uom' in flow %} {{ (flow.source_uom or '源单位未核实') | e }}{% endif %}{% if view.source_conversion %}；源订单库存换算系数：{{ flow.source_conversion_factor | e }}；源订单库存数量：{{ flow.source_stock_qty | e }} {{ flow.source_stock_uom | e }}{% endif %}</p>{% endif %}
{% if not view.plan_confirmed %}<p class="jf-warning">计划库存单位待核对，未列出物料总需求。</p>{% endif %}
{% if flow.get('source_changed') %}<p class="jf-warning">源单变更待确认{% if flow.get('source_change_note') %}：{{ flow.source_change_note | e }}{% endif %}</p>{% endif %}
{% if flow.get('stock_plan_confirmation_note') %}<p class="jf-note">计划单位核对说明：{{ flow.stock_plan_confirmation_note | e }}</p>{% endif %}
{% if 'requirements' in flow %}<h4>本单定制与工艺要求</h4><p class="jf-note">{{ (flow.requirements or '未填写') | e }}</p>{% endif %}
{% if 'packaging' in flow %}<h4>本单包装要求</h4><p class="jf-note">{{ (flow.packaging or '未填写') | e }}</p>{% endif %}
{% if view.material_fields %}<h4>物料分析</h4><table style="width:100%"><thead><tr>{% if 'item_code' in view.material_fields %}<th>物料</th>{% endif %}{% if 'qty_per_unit' in view.material_fields %}<th>每库存单位用量</th>{% if view.plan_confirmed and 'planned_qty' in flow %}<th>预计总需求</th>{% endif %}{% endif %}{% if 'uom' in view.material_fields %}<th>物料单位</th>{% endif %}{% if 'note' in view.material_fields %}<th>说明</th>{% endif %}</tr></thead><tbody>
{% for r in view.materials %}<tr>{% if 'item_code' in view.material_fields %}<td>{{ (r.get('item_code') or '') | e }}</td>{% endif %}{% if 'qty_per_unit' in view.material_fields %}<td>{{ r.get('qty_per_unit', '') | e }}</td>{% if view.plan_confirmed and 'planned_qty' in flow %}<td>{{ r.get('planned_requirement', '') | e }}</td>{% endif %}{% endif %}{% if 'uom' in view.material_fields %}<td>{{ (r.get('uom') or '') | e }}</td>{% endif %}{% if 'note' in view.material_fields %}<td>{{ (r.get('note') or '') | e }}</td>{% endif %}</tr>{% endfor %}</tbody></table>{% endif %}
{% if view.operation_fields %}<h4>工序顺序与预计工价</h4><table style="width:100%"><thead><tr>{% if 'idx' in view.operation_fields %}<th>序号</th>{% endif %}{% if 'operation' in view.operation_fields %}<th>工序</th>{% endif %}{% if 'supplier' in view.operation_fields %}<th>加工商</th>{% endif %}{% if 'unit_price' in view.operation_fields %}<th>预计每库存单位工价{% if view.currency %}（{{ view.currency | e }}）{% endif %}</th>{% endif %}{% if 'note' in view.operation_fields %}<th>要求</th>{% endif %}</tr></thead><tbody>{% for r in view.operations %}<tr>{% if 'idx' in view.operation_fields %}<td>{{ r.get('idx', '') | e }}</td>{% endif %}{% if 'operation' in view.operation_fields %}<td>{{ (r.get('operation') or '') | e }}</td>{% endif %}{% if 'supplier' in view.operation_fields %}<td>{{ (r.get('supplier') or '') | e }}</td>{% endif %}{% if 'unit_price' in view.operation_fields %}<td>{{ r.get('unit_price', '') | e }}{% if 'stock_uom' in flow and flow.stock_uom %} / {{ flow.stock_uom | e }}{% endif %}</td>{% endif %}{% if 'note' in view.operation_fields %}<td>{{ (r.get('note') or '') | e }}</td>{% endif %}</tr>{% endfor %}</tbody></table>{% endif %}
<p>物料总需求和工价用于计划；实际领料、报工、工资及成本以已提交的正式凭证为准。</p>
